<section class="section-wrap dashboard-page admin-page"><div class="dashboard-heading"><div><p class="eyebrow">HOW YOUR COLLECTION IS ORGANIZED</p><h1>Catalog<span class="brand-dot">.</span></h1><p>Shape the pathways through Shifa.</p></div></div><div class="catalog-grid"><section class="data-card catalog-column"><div class="card-heading"><div><p class="eyebrow">SHOP BY INTENTION</p><h2>Categories</h2></div></div><form class="catalog-create" method="post" action="<?= $e($base) ?>/admin/catalog/category"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input name="name" placeholder="New category name" maxlength="100" required><input name="description" placeholder="Short description"><button class="button button-dark">Add category ＋</button></form><?php foreach ($categories as $category): ?><form class="catalog-row" method="post" action="<?= $e($base) ?>/admin/catalog/category"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="id" value="<?= (int) $category['id'] ?>"><span class="catalog-id">#<?= (int) $category['id'] ?></span><input name="name" value="<?= $e($category['name']) ?>" required><input name="description" value="<?= $e($category['description'] ?? '') ?>" placeholder="Short description"><label class="check-label"><input type="checkbox" name="is_active" <?= (int) $category['is_active'] ? 'checked' : '' ?>> Active</label><button class="mini-action">Save</button><small><?= (int) $category['product_count'] ?> items</small></form><?php endforeach; ?></section><section class="data-card catalog-column"><div class="card-heading"><div><p class="eyebrow">THE MAKERS YOU LOVE</p><h2>Brands</h2></div></div><form class="catalog-create" method="post" action="<?= $e($base) ?>/admin/catalog/brand"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input name="name" placeholder="New brand name" maxlength="100" required><input name="logo" placeholder="Logo URL (optional)"><input name="discount_percent" type="number" min="0" max="100" step="0.01" placeholder="Discount %" value="0"><button class="button button-dark">Add brand ＋</button></form><?php foreach ($brands as $brand): ?><form class="catalog-row brand-row" method="post" action="<?= $e($base) ?>/admin/catalog/brand"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="id" value="<?= (int) $brand['id'] ?>"><span class="catalog-id">#<?= (int) $brand['id'] ?></span><input name="name" value="<?= $e($brand['name']) ?>" required><input name="logo" value="<?= $e($brand['logo'] ?? '') ?>" placeholder="Logo URL"><input name="discount_percent" type="number" min="0" max="100" step="0.01" value="<?= $e($brand['discount_percent']) ?>"><button class="mini-action">Save</button><small><?= (int) $brand['product_count'] ?> items</small></form><?php endforeach; ?></section></div></section>
